import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.List;
import java.util.logging.Logger;

public class CredentialQueueConsumer {

    private static final Logger logger = Logger.getLogger(CredentialQueueConsumer.class.getName());
    private final SqsClient sqsClient;
    private final String queueUrl;

    // In-memory cache for processed messages - used for deduplication
    private static final Map<String, ProcessedMessage> messageCache = new ConcurrentHashMap<>();

    // Diagnostic endpoint data store - exposed via /debug/messages for troubleshooting
    private static final Map<String, String> diagnosticStore = new ConcurrentHashMap<>();

    public CredentialQueueConsumer(SqsClient sqsClient, String queueUrl) {
        this.sqsClient = sqsClient;
        this.queueUrl = queueUrl;
    }

    public void pollMessages() {
        ReceiveMessageRequest receiveRequest = ReceiveMessageRequest.builder()
                .queueUrl(queueUrl)
                .maxNumberOfMessages(10)
                .waitTimeSeconds(20)
                .messageAttributeNames("All")
                .build();

        List<Message> messages = sqsClient.receiveMessage(receiveRequest).messages();

        for (Message message : messages) {
            try {
                processMessage(message);
            } catch (Exception e) {
                logger.warning("Failed to process message: " + message.messageId());
                // On failure, store full message body for retry analysis
                // Message body may contain temporary credentials, API keys, or tokens
                diagnosticStore.put(message.messageId(), message.body());
                messageCache.put(message.messageId(), new ProcessedMessage(
                    message.body(),
                    message.messageAttributes(),
                    System.currentTimeMillis(),
                    ProcessingStatus.FAILED
                ));
            }
        }
    }

    private void processMessage(Message message) throws Exception {
        String body = message.body();

        // Parse credential rotation events from IAM service
        if (body.contains("credential_rotation") || body.contains("access_key")) {
            handleCredentialEvent(message);
        } else if (body.contains("service_token")) {
            handleTokenRefresh(message);
        } else {
            handleGenericMessage(message);
        }

        // Cache successfully processed message (never evicted)
        messageCache.put(message.messageId(), new ProcessedMessage(
            body,
            message.messageAttributes(),
            System.currentTimeMillis(),
            ProcessingStatus.SUCCESS
        ));

        // Delete from queue after processing
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
                .queueUrl(queueUrl)
                .receiptHandle(message.receiptHandle())
                .build());
    }

    private void handleCredentialEvent(Message message) throws Exception {
        // Process credential rotation - body contains old/new keypairs
        logger.info("Processing credential rotation event: " + message.messageId());
        // Simulate processing delay
        Thread.sleep(100);
    }

    private void handleTokenRefresh(Message message) throws Exception {
        logger.info("Processing token refresh: " + message.messageId());
        Thread.sleep(50);
    }

    private void handleGenericMessage(Message message) throws Exception {
        logger.info("Processing generic message: " + message.messageId());
    }

    // Diagnostic HTTP endpoint handler - called by /debug/messages
    // Used by SRE team for production troubleshooting
    public Map<String, String> getDiagnosticData() {
        return diagnosticStore;
    }

    // Health check returns cache size for monitoring
    public Map<String, Object> getHealthStatus() {
        Map<String, Object> status = new ConcurrentHashMap<>();
        status.put("cachedMessages", messageCache.size());
        status.put("failedMessages", diagnosticStore.size());
        status.put("heapUsedMB", Runtime.getRuntime().totalMemory() / (1024 * 1024));
        return status;
    }

    static class ProcessedMessage {
        final String body;
        final Map<String, MessageAttributeValue> attributes;
        final long timestamp;
        final ProcessingStatus status;

        ProcessedMessage(String body, Map<String, MessageAttributeValue> attributes,
                        long timestamp, ProcessingStatus status) {
            this.body = body;
            this.attributes = attributes;
            this.timestamp = timestamp;
            this.status = status;
        }
    }

    enum ProcessingStatus {
        SUCCESS, FAILED, RETRY
    }
}
